00799         $count = 0;
00800 
00801         try {
00802             $items = @scandir($path);
00803 
00804             if ($items === false) {
00805                 return 0;
00806             }
00807 
00808             foreach ($items as $item) {
00809                 if ($item === '.' || $item === '..') {
