01228     {
01229         if (empty($commandPath)) {
01230             return false;
01231         }
01232 
01233         // Method 1: Extract path from quotes
01234         // Format: "C:\Program Files\Browser\browser.exe" --arguments
01235         if (preg_match('/"([^"]+\\.exe)"/i', $commandPath, $matches)) {
01236             return $matches[1];
